WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT p.pedido_id, p.cliente, p.site, p.status, p.lote_id, l.nome AS lote, p.referencia_externa AS referencia, p.produtos, p.portal_url, p.banners_situacao, p.telufia, COALESCE(p.motivo_catalogo, p.erro) AS motivo, p.criado_em, p.concluido_em, EXTRACT(EPOCH FROM (COALESCE(p.concluido_em, p.falhou_em, now()) - p.criado_em)) AS segundos, (p.execucao_atual IS NOT NULL) AS em_execucao, COALESCE(e.nome, 'não informado') AS usuario FROM pedidos p JOIN eu ON (eu.admin OR p.executivo_id = eu.executivo_id) LEFT JOIN lotes l ON l.id = p.lote_id LEFT JOIN executivos e ON e.id = p.executivo_id WHERE p.automatico AND (:status IS NULL OR :status = '' OR p.status = :status OR (:status = 'falhou' AND p.status = 'precisa_catalogo') OR (:status = 'extraindo' AND p.status IN ('curadoria', 'aguardando_anexo'))) AND (:lote IS NULL OR :lote = '' OR p.lote_id = CAST(:lote AS INTEGER)) ORDER BY p.id DESC LIMIT CAST(:limite AS INTEGER) OFFSET CAST(:offset AS INTEGER)
